{"command":"python3 << 'EOF'
import re

with open('reports/pipeline_report.md', 'r') as f:
    content = f.read()

# Split by sections
sections = re.split(r'^#\s+Overview|^#\s+Input data|^#\s+Methods|^#\s+Generated outputs|^#\s+Main results|^#\s+Limitations|^#\s+Reproducibility|^$', content, flags=re.MULTILINE)

# Each section should have at least one sentence (at least 80 characters)
for i, section in enumerate(sections):
    if section.strip():
        chars = len(section.strip())
        sentences = section.count('.') + section.count('!') + section.count('?')
        if chars >= 80:
            print(f"Section {i+1}: {chars} characters, {sentences} sentences - OK")
        else:
            print(f"Section {i+1}: {chars} characters, {sentences} sentences - TOO SHORT!")
    else:
        print(f"Section {i+1}: Empty section!")
EOF
"}

