headers = ['Overview', 'Input data', 'Methods', 'Generated outputs', 'Main results', 'Limitations', 'Reproducibility']

for header in headers:
    # Find the section content after the header
    start = content.find(f'#{header}')
    if start >= 0:
        end = content.find('\n\n', start + 2)
        if end == -1:
            end = len(content)
        section = content[start:end]
        chars = len(section)
        sentences = section.count('.') + section.count('!') + section.count('?')
        print(f"{header}: {chars} characters, {sentences} sentences - {'OK' if chars >= 80 else 'TOO SHORT'}")
    else:
        print(f"{header}: NOT FOUND!")
EOF
"}

